mapper.update:
UPDATE task
SET status = #{status}, current_stage = #{currentStage}
WHERE id = #{taskId}

UPDATE task
SET status = 'FAILED', current_stage = NULL,
    failure_stage = #{failureStage}, failure_reason = #{failureReason}
WHERE id = #{taskId}

UPDATE task
SET status = 'SUCCESS', current_stage = NULL, result_url = #{resultUrl}
WHERE id = #{taskId}
